def __setup__(cls):
    super().__setup__()
    t = cls.__table__()
    cls._sql_indexes.update({
            Index(
                t,
                (t.state, Index.Equality(cardinality='low')),
                where=t.state.in_(['draft', 'received'])),
            })
    cls._transitions |= set((
            ('draft', 'received'),
            ('received', 'done'),
            ('received', 'draft'),
            ('draft', 'cancelled'),
            ('received', 'cancelled'),
            ('cancelled', 'draft'),
            ('done', 'cancelled'),
            ))
    cls._buttons.update({
            'cancel': {
                'invisible': (
                    (Eval('state') == 'cancelled')
                    | ((Eval('state') == 'done')
                        & ~Id('stock',
                            'group_stock_cancellation').in_(
                            Eval('context', {}).get('groups', []))
                        & ~Eval('context', {}).get(
                            'administrator', False))),
                'depends': ['state'],
                },
            'draft': {
                'invisible': Eval('state') != 'cancelled',
                'depends': ['state'],
                },
            'receive': {
                'invisible': Eval('state') != 'draft',
                'depends': ['state'],
                },
            'do': {
                'invisible': Eval('state') != 'received',
                'depends': ['state'],
                },
            })
    cls.moves.domain = ['OR',
        cls.incoming_moves.domain,
        cls.inventory_moves.domain,
        ]

